17	/**
18	 * Evento global disparado quando qualquer request REST/RPC volta 401
19	 * (token JWT expirado/inválido). O AuthProvider escuta e decide: tenta
20	 * refresh e, falhando, faz signOut → tela de login. Cobre TODOS os escopos
21	 * (profiles, permissions, mia, lojas, telemetria) sem 401 em cascata preso.
22	 */
23	export const SESSION_UNAUTHORIZED_EVENT = 'supabase:unauthorized';
24	
25	const sessionGuardFetch: typeof fetch = async (input, init) => {
26	  const res = await fetch(input as RequestInfo, init);
27	  if (res.status === 401) {
28	    const url =
29	      typeof input === 'string'
30	        ? input
31	        : input instanceof URL
32	          ? input.href
33	          : (input as Request).url;
34	    // Ignorar 401 do próprio endpoint de auth (login/refresh) pra evitar loop
35	    if (!url.includes('/auth/v1/') && typeof window !== 'undefined') {
36	      try {
37	        window.dispatchEvent(new CustomEvent(SESSION_UNAUTHORIZED_EVENT));
38	      } catch {
39	        /* ambiente sem window — ignora */
40	      }
41	    }
42	  }
43	  return res;
44	};
