28	/**
29	 * Invoca a edge function MIA via Server-Sent Events (SSE).
30	 * Emite eventos tipados conforme MiaStreamEvent à medida que chegam.
31	 *
32	 * Instrumentação OTel:
33	 * - Span raiz  `mia.agent.invoke` com atributos: domain, round, model, fallback_level, user.role, store.id
34	 * - Span filho `mia.tool.call` para cada tool call com: tool.name, tool.parallel, tool.duration_ms
35	 * - Eventos `mia.streaming.start` e `mia.streaming.end` no span raiz
36	 * - Métricas: mia_requests_total, mia_tool_calls_total, mia_agent_duration_ms, mia_fallback_activations_total
37	 *
38	 * @throws MiaLLMError com código INFRA_EDGE_FUNCTION quando não autenticado ou HTTP error
39	 */
40	export async function callLLMStream(
41	  body: Record<string, unknown>,
42	  onEvent: (event: MiaStreamEvent) => void,
43	  signal?: AbortSignal,
44	): Promise<void> {
45	  // Inicializa métricas MIA (idempotente)
46	  await initMiaMetrics();
47	
48	  // Extrai metadados para atributos do span
49	  const pageContext = body.page_context as Record<string, unknown> | undefined;
50	  const domain = String(pageContext?.domain_hint ?? 'UNKNOWN');
51	  const storeId = String(pageContext?.store_id ?? '');
52	  const userProfile = pageContext?.user_profile as Record<string, unknown> | undefined;
53	  const userRole = String(userProfile?.role ?? '');
54	  const startTime = Date.now();
55	
56	  // Sem OTel habilitado — executa diretamente sem spans
57	  if (!isInitialized() || !getTelemetryConfig().enabled) {
58	    return _executeStream(body, domain, onEvent, signal, startTime, null, null, null);
59	  }
60	
61	  // Obtém tracer e cria span raiz via startActiveSpan (propaga contexto para filhos)
62	  const { trace: otelTrace, context: otelContext } = await import('@opentelemetry/api');
63	  const cfg = getTelemetryConfig();
64	  const tracer = otelTrace.getTracer(cfg.serviceName, cfg.serviceVersion);
65	
66	  return tracer.startActiveSpan(
67	    'mia.agent.invoke',
68	    {
69	      attributes: {
70	        'mia.agent.domain': domain,
71	        'mia.agent.round': '0',
72	        'mia.llm.model': 'unknown',
73	        'mia.llm.fallback_level': '0',
74	        'mia.store.id': storeId,
75	        'mia.user.role': userRole,
76	      },
77	    },
78	    async (rootSpan) => {
79	      // Captura contexto com o span raiz ativo para parenting dos spans filhos
80	      const spanContext = otelContext.active();
81	      return _executeStream(body, domain, onEvent, signal, startTime, rootSpan, tracer, spanContext);
82	    },
83	  );
84	}
